# Delete a shortcut from EVERY user's Desktop (matched by name pattern)
$ProfilePaths = Get-ADTUserProfiles | Select-Object -ExpandProperty 'ProfilePath'
foreach ($PPath in $ProfilePaths) {
    if (Test-Path -Path "$PPath\Desktop") {
        $ShortcutsToDelete = Get-ChildItem -Path "$PPath\Desktop" -Filter "<AppName>*.lnk"
        foreach ($shortcut in $ShortcutsToDelete) {
            Remove-ADTFile -Path $shortcut.FullName
        }
    }
}

# Find a product code by display name and uninstall (MSI)
$app = Get-ADTApplication -Name "<AppDisplayName>" -NameMatch Exact
if ($app -and $app.ProductCode) {
    Start-ADTMsiProcess -Action Uninstall -ProductCode $app.ProductCode
}

# Uninstall several MSI product codes in a loop
$ProductCodes = @(
    '<GUID1>',
    '<GUID2>',
    '<GUID3>'
)
foreach ($code in $ProductCodes) {
    Start-ADTMsiProcess -Action Uninstall -ProductCode $code
}

# Create a folder only if it does not already exist
if (-not (Test-Path -Path "$envSystemDrive\<RelativePath>")) {
    Write-ADTLogEntry -Message "Folder $envSystemDrive\<RelativePath> not present - creating it." -Severity 1
    New-ADTFolder -Path "$envSystemDrive\<RelativePath>"
}

# Remove empty sub-folders recursively under a base folder
if (Test-Path -Path "$envProgramData\<Vendor>") {
    $folders = Get-ChildItem -Path "$envProgramData\<Vendor>" -Force -Recurse |
        Sort-Object PSPath -Descending -Unique | Select-Object -ExpandProperty FullName
    foreach ($folder in $folders) {
        if ((Get-ChildItem -Path $folder | Measure-Object).Count -eq 0) {
            Remove-ADTFolder -Path $folder
        }
    }
}

# Remove leftover *.tmp files, then the folder(s) if now empty
if (Test-Path -Path "$envProgramFilesX86\<AppFolder>\bin") {
    Get-ChildItem -Path "$envProgramFilesX86\<AppFolder>\bin\*" -Include *.tmp |
        ForEach-Object { Remove-ADTFile -Path $_.FullName }
    if ($null -eq (Get-ChildItem "$envProgramFilesX86\<AppFolder>\bin")) {
        Remove-ADTFolder -Path "$envProgramFilesX86\<AppFolder>\bin"
    }
    if ($null -eq (Get-ChildItem "$envProgramFilesX86\<AppFolder>")) {
        Remove-ADTFolder -Path "$envProgramFilesX86\<AppFolder>"
    }
}

# Remove a registry value only when it equals an expected value
# NOTE: Wow6432Node is the 32-bit registry view - drop it for a 64-bit app.
$key = "HKLM:\SOFTWARE\Wow6432Node\<Vendor>\<SubKey>"
if (Test-Path -Path $key) {
    if ((Get-ADTRegistryKey -Key $key -Value '<ValueName>') -eq "<ExpectedValue>") {
        Remove-ADTRegistryKey -Key $key -Name "<ValueName>"
    }
}

# Back up a registry key by renaming it (before changing it)
if (Test-Path -Path "HKLM:\SOFTWARE\Classes\<.ext>") {
    Write-ADTLogEntry -Message "Backing up HKLM:\SOFTWARE\Classes\<.ext>" -Severity 1
    Rename-Item -Path "HKLM:\SOFTWARE\Classes\<.ext>" -NewName "<.ext>bckup"
}

# Stop and remove a Windows service (Stop-ServiceAndDependencies has no v4 equivalent -> native Stop-Service)
if (Get-Service -Name "<ServiceName>" -ErrorAction SilentlyContinue) {
    Stop-Service -Name "<ServiceName>" -Force -ErrorAction SilentlyContinue
    Get-CimInstance -ClassName Win32_Service -Filter "Name='<ServiceName>'" | Remove-CimInstance
}

# Remove a scheduled task (matches the tool's snapshot cleanup syntax)
if (Get-ScheduledTask -TaskName '<TaskName>' -ErrorAction SilentlyContinue) {
    Unregister-ScheduledTask -TaskName '<TaskName>' -TaskPath '<\Full\TaskPath\>' -Confirm:$false -ErrorAction SilentlyContinue
    Write-ADTLogEntry -Message 'Removed scheduled task <TaskName>.' -Severity 1
}

## Per-user settings applied to EVERY existing user + the default profile (new users inherit). Runs at install time.
## EDIT the registry value(s) this app needs under each user's HKCU (HKCU is auto-redirected per user via -SID).
Invoke-ADTAllUsersRegistryAction -ScriptBlock {
    Set-ADTRegistryKey -SID $_.SID -LiteralPath 'HKCU\Software\<Vendor>\<App>' -Name '<ValueName>' -Value '<Data>' -Type String
}

# Copy per-user file(s) into EVERY user profile (existing users + the Default profile, so NEW users inherit).
# Stage the file(s) in the package SupportFiles folder first. Put this block in POST-INSTALLATION.
[string[]]$ProfilePaths = Get-ADTUserProfiles | Select-Object -ExpandProperty 'ProfilePath'
foreach ($ProfilePath in $ProfilePaths) {
    Copy-ADTFile -Path "$($adtSession.DirSupportFiles)\<UserFile.ext>" -Destination "$ProfilePath\AppData\Roaming\<Vendor>\<App>"
    # Copy-ADTFile -Path "$($adtSession.DirSupportFiles)\<Other.ext>" -Destination "$ProfilePath\AppData\Local\<App>"
}

# --- Cleanup: put this block in POST-UNINSTALLATION (remove what was copied) ---
[string[]]$ProfilePaths = Get-ADTUserProfiles | Select-Object -ExpandProperty 'ProfilePath'
foreach ($ProfilePath in $ProfilePaths) {
    Remove-ADTFile -Path "$ProfilePath\AppData\Roaming\<Vendor>\<App>\<UserFile.ext>"
}
